"""DORÉ DESIGN 2.0 workbench shell augmentation.

Stage 2: stable Layers / Canvas / Properties IA, contextual selection properties,
keyboard workflow, command palette, inline text bridge and revision navigation.
"""
CSS=r'''<style id="d2-workbench-css">
:root{--d2-left:264px;--d2-right:300px}.work{grid-template-columns:var(--d2-left) minmax(0,1fr) var(--d2-right)!important}.top strong{min-width:190px}.d2-topgroup{display:flex;gap:4px}.d2-topgroup button{min-width:34px}.d2-layers-head{display:flex;justify-content:space-between;align-items:center;margin-top:14px}.layer{display:grid!important;grid-template-columns:18px 1fr;align-items:center;gap:5px}.layer .kind{opacity:.55;font-size:9px}.layer.active{outline:1px solid #8c6818}.d2-props{border-top:1px solid #bbb;margin-top:12px;padding-top:12px}.d2-props[hidden]{display:none}.d2-props h3{display:flex;justify-content:space-between}.d2-props .selection-count{font-weight:400;color:#777}.d2-inline-note{font:10px/1.45 Arial,sans-serif;color:#777;margin-top:7px}.d2-palette-backdrop{position:fixed;inset:0;z-index:30000;background:#0006;display:none;align-items:flex-start;justify-content:center;padding-top:12vh}.d2-palette-backdrop.on{display:flex}.d2-palette{width:min(620px,90vw);background:#f8f7f2;border:1px solid #222;box-shadow:0 20px 80px #0006}.d2-palette input{width:100%;border:0;border-bottom:1px solid #bbb;padding:15px;font:14px ui-monospace,monospace;outline:0}.d2-palette-list{max-height:360px;overflow:auto}.d2-command{padding:10px 14px;border-bottom:1px solid #ddd;cursor:pointer;display:flex;justify-content:space-between}.d2-command:hover,.d2-command.on{background:#e8dfc8}.d2-command small{color:#777}.d2-history{display:flex;gap:4px}.d2-history button{width:auto!important;margin:0!important;padding:6px 8px!important;background:#303030!important}.canvaswrap{position:relative}.d2-mode{position:absolute;left:26px;top:25px;z-index:3;background:#171717;color:#d0bd78;padding:5px 7px;font-size:9px;pointer-events:none}
</style>'''
PANEL=r'''<section id="d2Properties" class="d2-props" hidden><h3>PROPERTIES <span id="d2SelectionCount" class="selection-count"></span></h3><div id="d2SelectionMeta" class="hint"></div><label>TEXT</label><textarea id="d2Text" placeholder="Double-click text on canvas or edit here"></textarea><button id="d2SaveText">Apply text</button><div class="d2-inline-note">Double-click a text element on canvas for inline editing. Esc cancels; Cmd/Ctrl+Enter commits.</div></section>'''
PALETTE=r'''<div id="d2PaletteBack" class="d2-palette-backdrop"><div class="d2-palette"><input id="d2PaletteInput" placeholder="Type a command…"><div id="d2PaletteList" class="d2-palette-list"></div></div></div>'''
JS=r'''<script id="d2-workbench-js">(()=>{const $=id=>document.getElementById(id);let ids=[];const cmds=[['Undo','undo','⌘Z'],['Redo','redo','⇧⌘Z'],['Refresh workspace','refresh','⌘R'],['Preview page','preview',''],['Align left','left',''],['Align center','center',''],['Align right','right',''],['Align top','top',''],['Align middle','middle',''],['Align bottom','bottom',''],['Distribute horizontally','horizontal',''],['Distribute vertically','vertical','']];function page(){return ws?.pages?.find(p=>p.id===active)}function nodes(){return ids.map(id=>page()?.nodes?.find(n=>n.id===id)).filter(Boolean)}function drawProps(){const ns=nodes(),box=$('d2Properties');box.hidden=!ns.length;if(!ns.length)return;$('d2SelectionCount').textContent=ns.length===1?'1 ELEMENT':ns.length+' ELEMENTS';$('d2SelectionMeta').textContent=ns.map(n=>n.id).join(' · ');$('d2Text').disabled=ns.length!==1||ns[0].type!=='text';$('d2SaveText').disabled=$('d2Text').disabled;$('d2Text').value=(!$('d2Text').disabled?ns[0].text:'')||''}async function d2cmd(c){if(typeof command==='function')return command(c);const r=await fetch('/api/design2/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({expected_revision:ws.revision,command:c})}),j=await r.json();if(j.workspace){ws=j.workspace;renderLayers();$('canvas').src=canvasUrl();drawProps()}return r.ok}window.addEventListener('message',e=>{const m=e.data||{};if(m.type==='dore-selection'&&m.page_id===active){ids=m.ids||[];drawProps();highlightLayers()}if(m.type==='dore-inline-commit'&&m.page_id===active)d2cmd({op:'node.text',page_id:active,id:m.id,text:m.text})});function highlightLayers(){document.querySelectorAll('.layer').forEach(x=>x.classList.toggle('active',ids.includes(x.dataset.nodeId)))}const oldRender=renderLayers;renderLayers=function(){oldRender();document.querySelectorAll('.layer').forEach(x=>{const raw=x.textContent||'',id=raw.split(' · ')[0];x.dataset.nodeId=id;x.innerHTML='<span class="kind">◆</span><span>'+raw+'</span>';x.onclick=()=>{$('canvas').contentWindow.postMessage({type:'dore2-select-external',id},'*')}});highlightLayers()};$('d2SaveText').onclick=()=>{const n=nodes()[0];if(n)d2cmd({op:'node.text',page_id:active,id:n.id,text:$('d2Text').value})};async function historyAction(direction){const r=await fetch('/api/design2/history',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({direction,revision:ws.revision})}),j=await r.json();if(!r.ok){$('status').textContent=j.error||direction.toUpperCase()+' FAILED';return}ws=j.workspace;ids=[];renderPages();renderLayers();drawProps();$('canvas').src=canvasUrl();$('status').textContent=direction.toUpperCase()+' · r'+ws.revision}window.d2History=historyAction;function run(k){if(k==='undo'||k==='redo')return historyAction(k);if(k==='refresh')return $('refresh').click();if(k==='preview')return $('preview').click();if(['left','center','right','top','middle','bottom'].includes(k)&&ids.length>1)return d2cmd({op:'node.align',page_id:active,ids,edge:k});if(['horizontal','vertical'].includes(k)&&ids.length>2)return d2cmd({op:'node.distribute',page_id:active,ids,axis:k})}function drawPalette(q=''){const list=$('d2PaletteList'),needle=q.toLowerCase();list.innerHTML='';cmds.filter(c=>c[0].toLowerCase().includes(needle)).forEach((c,i)=>{const d=document.createElement('div');d.className='d2-command'+(i===0?' on':'');d.innerHTML='<span>'+c[0]+'</span><small>'+c[2]+'</small>';d.onclick=()=>{closePalette();run(c[1])};list.appendChild(d)})}function openPalette(){drawPalette();$('d2PaletteBack').classList.add('on');$('d2PaletteInput').value='';$('d2PaletteInput').focus()}function closePalette(){$('d2PaletteBack').classList.remove('on')}$('d2PaletteInput').oninput=e=>drawPalette(e.target.value);$('d2PaletteInput').onkeydown=e=>{if(e.key==='Escape')closePalette();if(e.key==='Enter'){const x=$('d2PaletteList').querySelector('.d2-command');if(x)x.click()}};$('d2PaletteBack').onclick=e=>{if(e.target===$('d2PaletteBack'))closePalette()};document.addEventListener('keydown',e=>{const mod=e.metaKey||e.ctrlKey;if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette();return}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();historyAction(e.shiftKey?'redo':'undo')}});const top=document.querySelector('.top');if(top){const g=document.createElement('span');g.className='d2-history';g.innerHTML='<button title="Undo · Cmd/Ctrl+Z">↶</button><button title="Redo · Shift+Cmd/Ctrl+Z">↷</button><button title="Command Palette · Cmd/Ctrl+K">⌘K</button>';g.children[0].onclick=()=>historyAction('undo');g.children[1].onclick=()=>historyAction('redo');g.children[2].onclick=openPalette;top.insertBefore(g,$('status'))}setTimeout(()=>{renderLayers();drawProps()},0)})()</script>'''
def augment(html):
    html=html.replace('</head>',CSS+'</head>',1)
    html=html.replace('<div id="inspector" hidden>',PANEL+'<div id="inspector" hidden>',1)
    html=html.replace('<main class="canvaswrap">','<main class="canvaswrap"><span class="d2-mode">CANONICAL DOCUMENT · DIRECT MANIPULATION</span>',1)
    return html.replace('</body>',PALETTE+JS+'</body>',1)
